                "sampleValue": "今天"
              },
              "temperatureRangeText": {
                "type": "string",
                "description": "当天温度范围展示文本。",
                "sampleValue": "24°/30°"
              },
              "rainProbabilityPercent": {
                "type": "string",
                "description": "当天降雨概率百分比。",
                "sampleValue": "80%"
              }
            }
          }
        },
        "updatedAt": {
          "type": "string",
          "description": "端侧完成天气查询和归一化的更新时间。",
          "sampleValue": "15:30"
        }
      }
    },
    "ui": {
      "iconFlashColor": {
        "type": "string",
        "description": "危险预警时用于雷雨图标底板闪烁提醒的提示色。",
        "sampleValue": "#ffdb6b42"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/thunderstorm.png",
      "description": "云朵、闪电和雨滴组合的彩色雷雨图标，适合作为天气预警卡片的大号主视觉。"
    }
  ]
}

